"doom-fps/public/game.js" "// game.js - Full Raycasting 3D Engine for Doom-style FPS

const socket = io();

// --- Game Configuration ---
const config = {
    mapSize: 32, // Size of the square map (e.g., 32x32 tiles)
    wallHeight: 64, // Height of walls in world units
    player: {
        fov: Math.PI / 3, // Field of View
        speed: 0.1, // Movement speed
        turnSpeed: 0.05, // Rotation speed
        height: 32, // Player height
    },
    raycaster: {
        numRays: 320, // Number of rays to cast (resolution)
        maxDistance: 600, // Max rendering distance
    }
};

// --- Game State ---
const gameState = {
    player: {
        x: config.mapSize * 16, // Player start X
        y: config.mapSize * 16, // Player start Y
        angle: Math.PI / 2, // Player start angle (facing right)
        health: 100,
        id: socket.id, // Assign player unique ID from socket
    },
    map: [], // 2D array representing the map (0=empty, 1=wall)
    otherPlayers: {}, // Stores other players' states
    bullets: [], // Stores active bullets/projectiles
};

// Initialize map with a border
for (let y = 0; y < config.mapSize; y++) {
    gameState.map[y] = [];
    for (let x = 0; x < config.mapSize; x++) {
        if (x === 0 || x === config.mapSize - 1 || y === 0 || y === config.mapSize - 1) {
            gameState.map[y][x] = 1; // Wall
        } else {
            gameState.map[y][x] = 0; // Empty space
        }
    }
}
// Add some internal walls for testing
gameState.map[5][5] = 1;
gameState.map[5][6] = 1;
gameState.map[6][5] = 1;
gameState.map[10][10] = 1;
gameState.map[10][11] = 1;
gameState.map[11][10] = 1;
gameState.map[11][11] = 1;

// --- Canvas Setup ---
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

// Adjust canvas size on window resize
window.addEventListener('resize', () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
    draw(); // Redraw on resize
});

// --- Raycasting Engine ---
function castRay(x, y, angle) {
    let hit = false;
    let distance = 0;
    let wallType = 0; // 0 for no hit, 1 for wall
    const stepSize = 1; // How much to increment along the ray

    while (distance < config.raycaster.maxDistance && !hit) {
        distance += stepSize;
        const currentX = x + Math.cos(angle) * distance;
        const currentY = y + Math.sin(angle) * distance;

        const mapX = Math.floor(currentX / config.wallHeight);
        const mapY = Math.floor(currentY / config.wallHeight);

        if (mapX < 0 || mapX >= config.mapSize || mapY < 0 || mapY >= config.mapSize) {
            // Ray went out of map bounds
            break;
        }

        if (gameState.map[mapY][mapX] === 1) {
            wallType = 1; // Hit a wall
            hit = true;
        }
    }

    return { distance, wallType, hit };
}

function renderWalls() {
    const viewAngle = config.player.fov;
    const startAngle = gameState.player.angle - viewAngle / 2;
    const endAngle = gameState.player.angle + viewAngle / 2;
    const angleStep = viewAngle / config.raycaster.numRays;

    for (let i = 0; i < config.raycaster.numRays; i++) {
        const rayAngle = startAngle + i * angleStep;
        const { distance, wallType } = castRay(gameState.player.x, gameState.player.y, rayAngle);

        // Correct for fisheye effect
        const correctedDistance = distance * Math.cos(rayAngle - gameState.player.angle);

        // Calculate wall height for rendering
        const projectedWallHeight = (config.wallHeight * canvas.height) / correctedDistance;

        // Calculate top and bottom of the wall slice
        const wallTop = (canvas.height / 2) - (projectedWallHeight / 2);
        const wallBottom = (canvas.height / 2) + (projectedWallHeight / 2);

        // Render wall slice
        if (wallType === 1) {
            ctx.fillStyle = `hsl(0, 0%, ${Math.max(0, 50 - (correctedDistance / config.raycaster.maxDistance) * 50)}%)`; // Simple shading
            ctx.fillRect(i * (canvas.width / config.raycaster.numRays), wallTop, (canvas.width / config.raycaster.numRays) + 1, projectedWallHeight);
        }

        // Draw floor and ceiling (simple flat colors for now)
        // Ceiling
        ctx.fillStyle = `rgb(100, 100, 200)`;
        ctx.fillRect(i * (canvas.width / config.raycaster.numRays), 0, (canvas.width / config.raycaster.numRays) + 1, wallTop);

        // Floor
        ctx.fillStyle = `rgb(50, 100, 50)`;
        ctx.fillRect(i * (canvas.width / config.raycaster.numRays), wallBottom, (canvas.width / config.raycaster.numRays) + 1, canvas.height - wallBottom);
    }
}

// --- Player Movement (WASD) ---
const keys = {};
window.addEventListener('keydown', e => keys[e.code] = true);
window.addEventListener('keyup', e => keys[e.code] = false);

function updatePlayerMovement() {
    const { player, map } = gameState;
    const { speed, turnSpeed } = config.player;
    const moveStep = speed;
    const turnStep = turnSpeed;

    let newX = player.x;
    let newY = player.y;
    let newAngle = player.angle;

    if (keys['KeyW']) { // Move forward
        newX += Math.cos(player.angle) * moveStep;
        newY += Math.sin(player.angle) * moveStep;
    }
    if (keys['KeyS']) { // Move backward
        newX -= Math.cos(player.angle) * moveStep;
        newY -= Math.sin(player.angle) * moveStep;
    }
    if (keys['KeyA']) { // Strafe left
        newX += Math.cos(player.angle - Math.PI / 2) * moveStep;
        newY += Math.sin(player.angle - Math.PI / 2) * moveStep;
    }
    if (keys['KeyD']) { // Strafe right
        newX -= Math.cos(player.angle - Math.PI / 2) * moveStep;
        newY -= Math.sin(player.angle - Math.PI / 2) * moveStep;
    }
    if (keys['ArrowLeft']) { // Turn left
        newAngle -= turnStep;
    }
    if (keys['ArrowRight']) { // Turn right
        newAngle += turnStep;
    }

    // Collision detection (simple square collision for player vs map walls)
    const playerRadius = config.wallHeight / 4; // Approx player size

    const checkCollision = (cx, cy) => {
        const mapGridX1 = Math.floor((cx - playerRadius) / config.wallHeight);
        const mapGridY1 = Math.floor((cy - playerRadius) / config.wallHeight);
        const mapGridX2 = Math.floor((cx + playerRadius) / config.wallHeight);
        const mapGridY2 = Math.floor((cy + playerRadius) / config.wallHeight);

        for (let y = mapGridY1; y <= mapGridY2; y++) {
            for (let x = mapGridX1; x <= mapGridX2; x++) {
                if (x >= 0 && x < config.mapSize && y >= 0 && y < config.mapSize && map[y][x] === 1) {
                    return true; // Collision detected
                }
            }
        }
        return false;
    };

    if (!checkCollision(newX, player.y)) {
        player.x = newX;
    }
    if (!checkCollision(player.x, newY)) {
        player.y = newY;
    }

    player.angle = newAngle % (Math.PI * 2); // Keep angle within 0-2PI

    // Emit player state to server
    socket.emit('playerMove', {
        x: player.x,
        y: player.y,
        angle: player.angle,
        id: player.id,
    });
}

// --- Mouse Look ---
let isPointerLocked = false;
canvas.addEventListener('click', () => {
    canvas.requestPointerLock();
});
document.addEventListener('pointerlockchange', () => {
    isPointerLocked = document.pointerLockElement === canvas;
});
document.addEventListener('mousemove', e => {
    if (isPointerLocked) {
        // Adjust player angle based on mouse movement
        gameState.player.angle += e.movementX * 0.002;
    }
});

// --- Shooting Mechanism ---
canvas.addEventListener('contextmenu', e => e.preventDefault()); // Prevent right-click context menu
canvas.addEventListener('mousedown', e => {
    if (isPointerLocked && e.button === 0) { // Left-click
        shootBullet();
    }
});

function shootBullet() {
    // Create a new bullet object
    const bullet = {
        x: gameState.player.x,
        y: gameState.player.y,
        angle: gameState.player.angle, // Bullet travels in player's current direction
        speed: 10,
        id: Math.random(), // Unique ID for bullet
        ownerId: gameState.player.id,
    };
    gameState.bullets.push(bullet);
    socket.emit('shoot', bullet);
}

function updateBullets() {
    gameState.bullets = gameState.bullets.filter(bullet => {
        bullet.x += Math.cos(bullet.angle) * bullet.speed;
        bullet.y += Math.sin(bullet.angle) * bullet.speed;

        // Check bullet collision with walls
        const mapX = Math.floor(bullet.x / config.wallHeight);
        const mapY = Math.floor(bullet.y / config.wallHeight);

        if (mapX < 0 || mapX >= config.mapSize || mapY < 0 || mapY >= config.mapSize || gameState.map[mapY][mapX] === 1) {
            return false; // Remove bullet if it hits a wall or goes out of bounds
        }

        // TODO: Check collision with other players

        return true; // Keep bullet if it's still flying
    });
}

// --- Multiplayer Synchronization (Socket.IO Client) ---
socket.on('connect', () => {
    console.log('Connected to server with ID:', socket.id);
    gameState.player.id = socket.id; // Ensure player ID is set
    socket.emit('playerJoin', gameState.player); // Inform server of new player
});

socket.on('playerUpdate', (players) => {
    gameState.otherPlayers = {}; // Clear existing to prevent stale data
    players.forEach(p => {
        if (p.id !== gameState.player.id) {
            gameState.otherPlayers[p.id] = p;
        }
    });
});

socket.on('playerLeave', (playerId) => {
    delete gameState.otherPlayers[playerId];
});

socket.on('bulletFired', (bullet) => {
    // Only add if not fired by this client to avoid duplicates
    if (bullet.ownerId !== gameState.player.id) {
        gameState.bullets.push(bullet);
    }
});

// --- Game Loop ---
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    debugger;

    renderWalls();
    // TODO: Render other players (as sprites/billboards)
    // TODO: Render bullets/projectiles

    // Mini-map (for debugging/overview)
