    // ctx.fillRect(canvas.width - miniMapSize - 10, 10, miniMapSize, miniMapSize);
    // for (let y = 0; y < config.mapSize; y++) {
    //     for (let x = 0; x < config.mapSize; x++) {
    //         if (gameState.map[y][x] === 1) {
    //             ctx.fillStyle = 'black';
    //             ctx.fillRect(canvas.width - miniMapSize - 10 + x * cellSize, 10 + y * cellSize, cellSize, cellSize);
